def build_gender_questions():
    questions = []
    for idx, item in enumerate(NOUNS_DATA, start=1):
        noun, article, plural, meaning_en, meaning_te, meaning_kn, example_de = item
        
        q_record = {
            "id": idx,
            "noun": noun,
            "article": article.strip().lower(),
            "plural": plural,
            "meaning_en": meaning_en,
            "meaning_te": meaning_te,
            "meaning_kn": meaning_kn,
            "example_de": example_de,
            "topic": f"Artikel Bestimmung: {noun}",
            "hint": f"Plural: {plural} | Meaning: {meaning_en}"
        }
        questions.append(q_record)

    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    out_dir = os.path.join(base_dir, "data")
    os.makedirs(out_dir, exist_ok=True)
    out_file = os.path.join(out_dir, "gender_questions_bank.json")
    with open(out_file, "w", encoding="utf-8") as f:
        json.dump(questions, f, ensure_ascii=False, indent=2)
    
    print(f"Successfully generated {len(questions)} gender questions in {out_file}!")


if __name__ == "__main__":
    build_gender_questions()
